package cn.sixnine.filmlog;

import android.app.*;
import android.content.*;
import android.content.res.Configuration;
import android.graphics.Bitmap;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.io.*;
import java.time.LocalDate;
import java.util.*;

/** Native continuous sections and the existing lab forms, only in an isolated workspace. */
public final class RollSectionsInstrumentation extends Instrumentation {
    private MainActivity activity;private LogStore logs;private Configuration original;
    private String live,live2,pending,lab,received,archivedReceived,manual;
    interface Action{void run()throws Exception;}
    private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    private void main(Action action)throws Exception{Throwable[] error={null};runOnMainSync(()->{try{action.run();}catch(Throwable e){error[0]=e;}});waitForIdleSync();if(error[0]!=null)throw new RuntimeException(error[0]);}
    private Object get(String name)throws Exception{java.lang.reflect.Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
    private Object call(String name,Class<?>[] types,Object... args)throws Exception{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}
    private ViewGroup root()throws Exception{return (ViewGroup)get("root");}
    private View tagged(String tag)throws Exception{View v=root().findViewWithTag(tag);check(v!=null,"missing "+tag);return v;}
    private ScrollView scroll()throws Exception{return (ScrollView)get("pageScroll");}
    private List<View> tree(View v){ArrayList<View> out=new ArrayList<>();out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.addAll(tree(((ViewGroup)v).getChildAt(i)));return out;}
    private List<String> ids(View v){ArrayList<String> out=new ArrayList<>();for(View child:tree(v))if(child.getTag() instanceof String&&((String)child.getTag()).startsWith("roll-list-item:"))out.add(((String)child.getTag()).substring("roll-list-item:".length()));return out;}
    private void count(String group,int expected)throws Exception{check(((TextView)tagged("roll-section-count:"+group)).getText().toString().equals(expected+" 卷"),"group count "+group+" "+expected);}
    private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
    private int top(View v){int[] pos=new int[2];v.getLocationInWindow(pos);return pos[1];}
    private Dialog dialog()throws Exception{return (Dialog)get("rollSheet");}
    private View form(String tag)throws Exception{View v=dialog().getWindow().getDecorView().findViewWithTag(tag);check(v!=null,"form "+tag);return v;}
    private void snapshot(String name)throws Exception{waitForIdleSync();SystemClock.sleep(350);Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"screenshot");File dir=new File(activity.getExternalFilesDir(null),"roll-sections");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
    private String fixture(LogStore db,String name,String state,boolean archived,String date){String id=new CatalogStore(db).manual(UUID.randomUUID().toString(),name,"Kodak Ultramax 400","Nikon FE2",400,36,"35 mm","","","original:kodak_ultramax_400");db.insert(id,10000,0,480,"denied","","","","","","");db.getWritableDatabase().execSQL("UPDATE rolls SET state=?,archived=?,lab_sent_date=?,lab_received_date=?,lab=?,created_at=? WHERE id=?",new Object[]{state,archived?1:0,state.equals("developing")?"2026-10-20":"",state.equals("received")?date:"",state.equals("developing")?"Test lab":"",LocalDate.parse(date).atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli(),id});return id;}
    @SuppressWarnings("deprecation") private void layout(boolean dark,int width)throws Exception{Configuration c=new Configuration(original);c.uiMode=(c.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|(dark?Configuration.UI_MODE_NIGHT_YES:Configuration.UI_MODE_NIGHT_NO);c.fontScale=dark?1.6f:1;c.screenWidthDp=width;activity.getResources().updateConfiguration(c,activity.getResources().getDisplayMetrics());call("render",new Class<?>[]{});View r=root();r.measure(View.MeasureSpec.makeMeasureSpec(dp(width),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(dp(780),View.MeasureSpec.EXACTLY));r.layout(0,0,r.getMeasuredWidth(),r.getMeasuredHeight());}
    private void structure()throws Exception{
        count("active",3);count("developing",1);count("archived",34);List<String> current=ids(tagged("roll-section:active"));check(current.size()==3&&current.get(2).equals(pending),"pending after all active rolls");List<String> history=ids(tagged("roll-section:archived"));check(history.size()==12&&history.contains(received)&&history.contains(archivedReceived)&&history.contains(manual),"archive union and first page");check(new HashSet<>(ids(root())).size()==ids(root()).size(),"never double-list archived received");check(root().findViewWithTag("roll-list-phase:"+pending)!=null&&root().findViewWithTag("roll-list-phase:"+lab)!=null,"pending and lab direct form actions");
        for(boolean dark:new boolean[]{false,true})for(int width:new int[]{320,375,414,768}){layout(dark,width);check(((android.graphics.drawable.ColorDrawable)root().getBackground()).getColor()==activity.getColor(R.color.ui_background),"theme root background matches text "+dark);check(root().findViewWithTag("roll-section:active")!=null&&root().findViewWithTag("roll-section:developing")!=null&&root().findViewWithTag("roll-section:archived")!=null,"all three groups expanded "+width);View toolbar=tagged("roll-list-toolbar");for(View v:tree(toolbar))if(v instanceof Button&&v.isShown()){TextView b=(TextView)v;check(b.getLineCount()<=1,"nav action never wraps "+width+" "+b.getText());check(v.getWidth()>=dp(40),"usable toolbar target "+width+" "+b.getText()+" actual="+v.getWidth());}scroll().scrollTo(0,dp(240));check(Math.abs(top(toolbar)-top(scroll()))<=1,"search/navigation stays pinned "+width);check(scroll().getScrollX()==0,"vertical list only");}
        activity.getResources().updateConfiguration(original,activity.getResources().getDisplayMetrics());call("render",new Class<?>[]{});
    }
    private void touch(String tag)throws Exception{int[] point=new int[2];main(()->{View v=tagged(tag);v.getLocationOnScreen(point);point[0]+=v.getWidth()/2;point[1]+=v.getHeight()/2;});long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,point[0],point[1],0),up=MotionEvent.obtain(now,now+50,MotionEvent.ACTION_UP,point[0],point[1],0);try{sendPointerSync(down);sendPointerSync(up);}finally{down.recycle();up.recycle();}waitForIdleSync();}
    private void navigationAndSearch()throws Exception{
        main(()->tagged("roll-section-jump:archived").performClick());SystemClock.sleep(400);main(()->{check(get("screen").equals("home")&&ids(root()).size()==16,"jump never filters or opens a page");check(tagged("roll-section-jump:archived").isSelected(),"archive jump selected");check(scroll().getScrollY()>0,"jump scrolls existing list");});snapshot("01-archive");touch("roll-section-jump:developing");SystemClock.sleep(400);main(()->check(get("screen").equals("home")&&tagged("roll-section-jump:developing").isSelected(),"touching transformed sticky toolbar hits navigation, not covered roll"));touch("roll-section-jump:archived");SystemClock.sleep(400);
        main(()->tagged("roll-load-earlier").performClick());main(()->{count("archived",34);check(ids(tagged("roll-section:archived")).size()==24,"load earlier appends same group");Bundle saved=new Bundle();callActivityOnSaveInstanceState(activity,saved);check(saved.getInt("rollArchiveLimit")==24&&saved.getInt("rollScrollY")==scroll().getScrollY(),"position and loaded history saved");});
        final int[] position={0};main(()->{position[0]=scroll().getScrollY();tagged("roll-list-item:"+received).performClick();check(get("screen").equals("roll")&&get("rollId").equals(received),"row binds stable roll ID");activity.onBackPressed();});main(()->check(get("screen").equals("home")&&Math.abs(scroll().getScrollY()-position[0])<=1,"detail return preserves list position"));
        main(()->((EditText)tagged("roll-search")).setText("History30"));main(()->{check(ids(root()).size()==1&&root().findViewWithTag("roll-load-earlier")==null,"search covers history beyond loaded page");count("active",0);count("archived",1);});
        main(()->((EditText)tagged("roll-search")).setText("NIKON"));main(()->{count("active",3);count("developing",1);count("archived",34);check(ids(root()).size()==38,"search all phases and all history case-insensitively");});
        main(()->((EditText)tagged("roll-search")).setText("missing-test-model"));main(()->check(root().findViewWithTag("roll-search-empty")!=null&&ids(root()).isEmpty(),"single no-result state"));main(()->{((EditText)tagged("roll-search")).setText("");call("cancelRollSearch",new Class<?>[]{});});main(()->{count("active",3);check(ids(tagged("roll-section:archived")).size()==12,"clearing search restores paging");});snapshot("02-light-list");main(()->{Configuration c=new Configuration(original);c.uiMode=(c.uiMode&~Configuration.UI_MODE_NIGHT_MASK)|Configuration.UI_MODE_NIGHT_YES;c.fontScale=1.6f;activity.getResources().updateConfiguration(c,activity.getResources().getDisplayMetrics());call("render",new Class<?>[]{});});snapshot("02-dark-large-list");main(()->{activity.getResources().updateConfiguration(original,activity.getResources().getDisplayMetrics());call("render",new Class<?>[]{});});
    }
    private void labFlow()throws Exception{
        main(()->{tagged("roll-list-phase:"+pending).performClick();check(get("screen").equals("home"),"send sheet stays over list");((EditText)form("lab-lab")).setText("List lab");dialog().cancel();});main(()->{check(logs.roll(pending).state.equals("finished"),"cancel keeps pending state");tagged("roll-list-phase:"+pending).performClick();((EditText)form("lab-lab")).setText("List lab");((EditText)form("lab-cost")).setText("35");form("lab-save").performClick();});main(()->{check(get("screen").equals("home")&&logs.roll(pending).state.equals("developing"),"send moves in same list");count("active",2);count("developing",2);check(ids(tagged("roll-section:developing")).contains(pending)&&!ids(tagged("roll-section:active")).contains(pending),"sent roll unique in new phase");tagged("roll-list-phase:"+pending).performClick();check(((EditText)form("lab-cost")).getText().toString().equals("35"),"existing receive form carries fee");dialog().cancel();});
        main(()->{check(logs.roll(pending).state.equals("developing"),"receive cancellation preserves phase");tagged("roll-list-phase:"+pending).performClick();form("lab-save").performClick();});main(()->{LogStore.Roll r=logs.roll(pending);check(get("screen").equals("home")&&r.state.equals("received")&&!r.archived&&r.count==1&&!r.receivedDate.isEmpty()&&r.labCost.equals("35"),"receive preserves state/date/records without extra archive write");count("developing",1);count("archived",35);check(Collections.frequency(ids(root()),pending)==1&&ids(tagged("roll-section:archived")).contains(pending),"received directly appears once in archive");call("rollActions",new Class<?>[]{LogStore.Roll.class},r);check(dialog().getWindow().getDecorView().findViewWithTag("roll-action:归档胶卷")==null,"no redundant archive step for received");dialog().cancel();});snapshot("03-received-in-archive");
        main(()->{call("confirmDeleteRoll",new Class<?>[]{LogStore.Roll.class},logs.roll(live2));check(logs.roll(live2).count==1,"delete requires confirmation");dialog().cancel();call("confirmDeleteRoll",new Class<?>[]{LogStore.Roll.class},logs.roll(live2));form("confirm-delete-roll").performClick();});main(()->check(get("screen").equals("home")&&logs.rolls().size()==37,"confirmed isolated delete stays in list and keeps other rolls"));
    }
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Context context=getTargetContext();String previous=Workspace.current(context);Bundle result=new Bundle();boolean passed=false;try{
        check(context.getPackageName().equals("cn.sixnine.filmlog.ui.tests"),"isolated UI identity");Workspace.activate(context,UUID.randomUUID().toString());try(LogStore db=new LogStore(Workspace.context(context))){live=fixture(db,"Live A","active",false,"2026-10-27");live2=fixture(db,"Live B","active",false,"2026-10-26");pending=fixture(db,"Pending","finished",false,"2026-10-25");lab=fixture(db,"At lab","developing",false,"2026-10-24");received=fixture(db,"Received","received",false,"2026-10-23");archivedReceived=fixture(db,"Received archived","received",true,"2026-10-22");manual=fixture(db,"Manual archive","active",true,"2026-10-21");for(int i=0;i<31;i++)fixture(db,"History"+i,"received",false,LocalDate.of(2025,1,1).minusDays(i).toString());}
        activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();original=new Configuration(activity.getResources().getConfiguration());main(()->{logs=(LogStore)get("store");call("activateTab",new Class<?>[]{String.class},"home");});main(this::structure);navigationAndSearch();labFlow();
        main(()->activity.finish());Workspace.activate(context,UUID.randomUUID().toString());activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();main(()->{logs=(LogStore)get("store");call("activateTab",new Class<?>[]{String.class},"home");});main(()->{count("active",0);count("developing",0);count("archived",0);check(ids(root()).isEmpty()&&root().findViewWithTag("new-roll-fab")!=null,"empty library keeps three light empty sections and create action");});SystemClock.sleep(4000);snapshot("04-empty");
        result.putString("stream","PASS: continuous three sections, pending-last, received/archive union without duplicate or data rewrite, four widths/light/dark1.6, sticky search/navigation and actual injected touch on its translated position, empty library, non-filtering anchors, 12-to24 history load, global search beyond loaded rows, no-result and clear, saved scroll/page state and detail return; existing send/receive save/cancel forms stay on list, correct stable-ID phase movement and preserved date/fee/count; no duplicate archive step; double-confirm isolated delete stays on list. No phone acceptance.\n");passed=true;
    }catch(Throwable error){result.putString("stream",android.util.Log.getStackTraceString(error));}finally{try{if(activity!=null)main(()->{if(original!=null)activity.getResources().updateConfiguration(original,activity.getResources().getDisplayMetrics());activity.finish();});}catch(Exception ignored){}Workspace.activate(context,previous);}finish(passed?-1:0,result);}
}
